INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヒヨリ", 1, "vo_empress_100101_001", 100101, 1, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", 1, 4, "", 0, "vo_empress_100101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヒヨリ", 1, "vo_empress_100101_002", 100103, 2, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", 1, 4, "", 0, "vo_empress_100101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヒヨリ", 2, "vo_empress_100101_003", 100103, 3, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", 1, 4, "", 0, "vo_empress_100101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヒヨリ", 3, "vo_empress_100101_004", 100102, 4, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", 1, 4, "", 100101, "vo_empress_100101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユイ", 1, "vo_empress_100201_001", 100203, 5, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", 1, 4, "", 0, "vo_empress_100201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユイ", 1, "vo_empress_100201_002", 100203, 6, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", 1, 4, "", 0, "vo_empress_100201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユイ", 2, "vo_empress_100201_003", 100203, 7, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", 1, 4, "", 0, "vo_empress_100201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユイ", 3, "vo_empress_100201_004", 100202, 8, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", 1, 4, "", 100201, "vo_empress_100201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "レイ", 1, "vo_empress_100301_001", 100301, 9, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", 1, 4, "", 0, "vo_empress_100301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "レイ", 1, "vo_empress_100301_002", 100303, 10, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", 1, 4, "", 0, "vo_empress_100301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "レイ", 2, "vo_empress_100301_003", 100303, 11, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", 1, 4, "", 0, "vo_empress_100301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "レイ", 3, "vo_empress_100301_004", 100302, 12, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", 1, 4, "", 100301, "vo_empress_100301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミソギ", 1, "vo_empress_100401_001", 100401, 13, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", 1, 4, "", 0, "vo_empress_100401_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミソギ", 1, "vo_empress_100401_002", 100401, 14, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", 1, 4, "", 0, "vo_empress_100401_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミソギ", 2, "vo_empress_100401_003", 100403, 15, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", 1, 4, "", 0, "vo_empress_100401_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミソギ", 3, "vo_empress_100401_004", 100402, 16, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", 1, 4, "", 100401, "vo_empress_100401_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マツリ", 1, "vo_empress_100501_001", 100501, 17, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", 1, 4, "", 0, "vo_empress_100501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マツリ", 1, "vo_empress_100501_002", 100501, 18, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", 1, 4, "", 0, "vo_empress_100501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マツリ", 2, "vo_empress_100501_003", 100503, 19, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", 1, 4, "", 0, "vo_empress_100501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マツリ", 3, "vo_empress_100501_004", 100502, 20, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", 1, 4, "", 100501, "vo_empress_100501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アカリ", 1, "vo_empress_100601_001", 100603, 21, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", 1, 4, "", 0, "vo_empress_100601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アカリ", 1, "vo_empress_100601_002", 100601, 22, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", 1, 4, "", 0, "vo_empress_100601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アカリ", 2, "vo_empress_100601_003", 100603, 23, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", 1, 4, "", 0, "vo_empress_100601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アカリ", 3, "vo_empress_100601_004", 100602, 24, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", 1, 4, "", 100601, "vo_empress_100601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミヤコ", 1, "vo_empress_100701_001", 100701, 25, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", 1, 4, "", 0, "vo_empress_100701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミヤコ", 1, "vo_empress_100701_002", 100702, 26, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", 1, 4, "", 0, "vo_empress_100701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミヤコ", 2, "vo_empress_100701_003", 100703, 27, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", 1, 4, "", 0, "vo_empress_100701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミヤコ", 3, "vo_empress_100701_004", 100702, 28, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", 1, 4, "", 100701, "vo_empress_100701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユキ", 1, "vo_empress_100801_001", 100801, 29, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", 1, 4, "", 0, "vo_empress_100801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユキ", 1, "vo_empress_100801_002", 100801, 30, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", 1, 4, "", 0, "vo_empress_100801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユキ", 2, "vo_empress_100801_003", 100801, 31, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", 1, 4, "", 0, "vo_empress_100801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユキ", 3, "vo_empress_100801_004", 100802, 32, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", 1, 4, "", 100801, "vo_empress_100801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アンナ", 1, "vo_empress_100901_001", 100901, 33, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", 1, 4, "", 0, "vo_empress_100901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アンナ", 1, "vo_empress_100901_002", 100903, 34, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", 1, 4, "", 0, "vo_empress_100901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アンナ", 2, "vo_empress_100901_003", 100903, 35, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", 1, 4, "", 0, "vo_empress_100901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アンナ", 3, "vo_empress_100901_004", 100902, 36, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", 1, 4, "", 100901, "vo_empress_100901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マホ", 1, "vo_empress_101001_001", 101001, 37, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", 1, 4, "", 0, "vo_empress_101001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マホ", 1, "vo_empress_101001_002", 101001, 38, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", 1, 4, "", 0, "vo_empress_101001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マホ", 2, "vo_empress_101001_003", 101003, 39, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", 1, 4, "", 0, "vo_empress_101001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マホ", 3, "vo_empress_101001_004", 101002, 40, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", 1, 4, "", 101001, "vo_empress_101001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リノ", 1, "vo_empress_101101_001", 101101, 41, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", 1, 4, "", 0, "vo_empress_101101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リノ", 1, "vo_empress_101101_002", 101101, 42, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", 1, 4, "", 0, "vo_empress_101101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リノ", 2, "vo_empress_101101_003", 101103, 43, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", 1, 4, "", 0, "vo_empress_101101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リノ", 3, "vo_empress_101101_004", 101102, 44, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", 1, 4, "", 101101, "vo_empress_101101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ハツネ", 1, "vo_empress_101201_001", 101201, 45, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", 1, 4, "", 0, "vo_empress_101201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ハツネ", 1, "vo_empress_101201_002", 101202, 46, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", 1, 4, "", 0, "vo_empress_101201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ハツネ", 2, "vo_empress_101201_003", 101203, 47, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", 1, 4, "", 0, "vo_empress_101201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ハツネ", 3, "vo_empress_101201_004", 101202, 48, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", 1, 4, "", 101201, "vo_empress_101201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ナナカ", 1, "vo_empress_101301_001", 101301, 49, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", 1, 4, "", 0, "vo_empress_101301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ナナカ", 1, "vo_empress_101301_002", 101301, 50, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", 1, 4, "", 0, "vo_empress_101301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ナナカ", 2, "vo_empress_101301_003", 101303, 51, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", 1, 4, "", 0, "vo_empress_101301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ナナカ", 3, "vo_empress_101301_004", 101302, 52, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", 1, 4, "", 101301, "vo_empress_101301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カスミ", 1, "vo_empress_101401_001", 101401, 53, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", 1, 4, "", 0, "vo_empress_101401_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カスミ", 1, "vo_empress_101401_002", 101401, 54, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", 1, 4, "", 0, "vo_empress_101401_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カスミ", 2, "vo_empress_101401_003", 101403, 55, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", 1, 4, "", 0, "vo_empress_101401_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カスミ", 3, "vo_empress_101401_004", 101402, 56, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", 1, 4, "", 101401, "vo_empress_101401_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミサト", 1, "vo_empress_101501_001", 101501, 57, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", 1, 4, "", 0, "vo_empress_101501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミサト", 1, "vo_empress_101501_002", 101501, 58, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", 1, 4, "", 0, "vo_empress_101501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミサト", 2, "vo_empress_101501_003", 101501, 59, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", 1, 4, "", 0, "vo_empress_101501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミサト", 3, "vo_empress_101501_004", 101502, 60, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", 1, 4, "", 101501, "vo_empress_101501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "スズナ", 1, "vo_empress_101601_001", 101601, 61, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", 1, 4, "", 0, "vo_empress_101601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "スズナ", 1, "vo_empress_101601_002", 101601, 62, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", 1, 4, "", 0, "vo_empress_101601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "スズナ", 2, "vo_empress_101601_003", 101601, 63, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", 1, 4, "", 0, "vo_empress_101601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "スズナ", 3, "vo_empress_101601_004", 101602, 64, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", 1, 4, "", 101601, "vo_empress_101601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カオリ", 1, "vo_empress_101701_001", 101701, 65, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", 1, 4, "", 0, "vo_empress_101701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カオリ", 1, "vo_empress_101701_002", 101701, 66, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", 1, 4, "", 0, "vo_empress_101701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カオリ", 2, "vo_empress_101701_003", 101703, 67, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", 1, 4, "", 0, "vo_empress_101701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カオリ", 3, "vo_empress_101701_004", 101702, 68, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", 1, 4, "", 101701, "vo_empress_101701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イオ", 1, "vo_empress_101801_001", 101801, 69, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", 1, 4, "", 0, "vo_empress_101801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イオ", 1, "vo_empress_101801_002", 101801, 70, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", 1, 4, "", 0, "vo_empress_101801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イオ", 2, "vo_empress_101801_003", 101803, 71, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", 1, 4, "", 0, "vo_empress_101801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イオ", 3, "vo_empress_101801_004", 101802, 72, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", 1, 4, "", 101801, "vo_empress_101801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミミ", 1, "vo_empress_102001_001", 102003, 73, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", 1, 4, "", 0, "vo_empress_102001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミミ", 1, "vo_empress_102001_002", 102003, 74, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", 1, 4, "", 0, "vo_empress_102001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミミ", 2, "vo_empress_102001_003", 102003, 75, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", 1, 4, "", 0, "vo_empress_102001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミミ", 3, "vo_empress_102001_004", 102002, 76, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", 1, 4, "", 102001, "vo_empress_102001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クルミ", 1, "vo_empress_102101_001", 102101, 77, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", 1, 4, "", 0, "vo_empress_102101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クルミ", 1, "vo_empress_102101_002", 102101, 78, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", 1, 4, "", 0, "vo_empress_102101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クルミ", 2, "vo_empress_102101_003", 102101, 79, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", 1, 4, "", 0, "vo_empress_102101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クルミ", 3, "vo_empress_102101_004", 102102, 80, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", 1, 4, "", 102101, "vo_empress_102101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヨリ", 1, "vo_empress_102201_001", 102201, 81, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", 1, 4, "", 0, "vo_empress_102201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヨリ", 1, "vo_empress_102201_002", 102201, 82, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", 1, 4, "", 0, "vo_empress_102201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヨリ", 2, "vo_empress_102201_003", 102203, 83, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", 1, 4, "", 0, "vo_empress_102201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヨリ", 3, "vo_empress_102201_004", 102202, 84, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", 1, 4, "", 102201, "vo_empress_102201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アヤネ", 1, "vo_empress_102301_001", 102301, 85, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", 1, 4, "", 0, "vo_empress_102301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アヤネ", 1, "vo_empress_102301_002", 102303, 86, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", 1, 4, "", 0, "vo_empress_102301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アヤネ", 2, "vo_empress_102301_003", 102303, 87, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", 1, 4, "", 0, "vo_empress_102301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アヤネ", 3, "vo_empress_102301_004", 102302, 88, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", 1, 4, "", 102301, "vo_empress_102301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "スズメ", 1, "vo_empress_102501_001", 102503, 89, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", 1, 4, "", 0, "vo_empress_102501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "スズメ", 1, "vo_empress_102501_002", 102503, 90, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", 1, 4, "", 0, "vo_empress_102501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "スズメ", 2, "vo_empress_102501_003", 102503, 91, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", 1, 4, "", 0, "vo_empress_102501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "スズメ", 3, "vo_empress_102501_004", 102502, 92, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", 1, 4, "", 102501, "vo_empress_102501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リン", 1, "vo_empress_102601_001", 102603, 93, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", 1, 4, "", 0, "vo_empress_102601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リン", 1, "vo_empress_102601_002", 102603, 94, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", 1, 4, "", 0, "vo_empress_102601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リン", 2, "vo_empress_102601_003", 102603, 95, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", 1, 4, "", 0, "vo_empress_102601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リン", 3, "vo_empress_102601_004", 102602, 96, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", 1, 4, "", 102601, "vo_empress_102601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "エリコ", 1, "vo_empress_102701_001", 102701, 97, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", 1, 4, "", 0, "vo_empress_102701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "エリコ", 1, "vo_empress_102701_002", 102701, 98, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", 1, 4, "", 0, "vo_empress_102701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "エリコ", 2, "vo_empress_102701_003", 102703, 99, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", 1, 4, "", 0, "vo_empress_102701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "エリコ", 3, "vo_empress_102701_004", 102702, 100, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", 1, 4, "", 102701, "vo_empress_102701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "サレン", 1, "vo_empress_102801_001", 102801, 101, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", 1, 4, "", 0, "vo_empress_102801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "サレン", 4002, "vo_empress_102801_002", 102801, 102, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 1, 4, 1, 0, "vo_empress_102801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "サレン", 2, "vo_empress_102801_003", 102803, 103, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", 1, 4, "", 0, "vo_empress_102801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "サレン", 3, "vo_empress_102801_004", 102802, 104, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", 1, 4, "", 102801, "vo_empress_102801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ノゾミ", 1, "vo_empress_102901_001", 102903, 105, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", 1, 4, "", 0, "vo_empress_102901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ノゾミ", 1, "vo_empress_102901_002", 102903, 106, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", 1, 4, "", 0, "vo_empress_102901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ノゾミ", 2, "vo_empress_102901_003", 102903, 107, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", 1, 4, "", 0, "vo_empress_102901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ノゾミ", 3, "vo_empress_102901_004", 102901, 108, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", 1, 4, "", 102901, "vo_empress_102901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ニノン", 1, "vo_empress_103001_001", 103001, 109, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", 1, 4, "", 0, "vo_empress_103001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ニノン", 1, "vo_empress_103001_002", 103001, 110, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", 1, 4, "", 0, "vo_empress_103001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ニノン", 2, "vo_empress_103001_003", 103003, 111, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", 1, 4, "", 0, "vo_empress_103001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ニノン", 3, "vo_empress_103001_004", 103002, 112, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", 1, 4, "", 103001, "vo_empress_103001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シノブ", 1, "vo_empress_103101_001", 103101, 113, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", 1, 4, "", 0, "vo_empress_103101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シノブ", 1, "vo_empress_103101_002", 103101, 114, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", 1, 4, "", 0, "vo_empress_103101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シノブ", 2, "vo_empress_103101_003", 103103, 115, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", 1, 4, "", 0, "vo_empress_103101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シノブ", 3, "vo_empress_103101_004", 103101, 116, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", 1, 4, "", 103101, "vo_empress_103101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アキノ", 1, "vo_empress_103201_001", 103201, 117, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", 1, 4, "", 0, "vo_empress_103201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アキノ", 1, "vo_empress_103201_002", 103201, 118, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", 1, 4, "", 0, "vo_empress_103201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アキノ", 2, "vo_empress_103201_003", 103203, 119, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", 1, 4, "", 0, "vo_empress_103201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アキノ", 3, "vo_empress_103201_004", 103202, 120, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", 1, 4, "", 103201, "vo_empress_103201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マヒル", 1, "vo_empress_103301_001", 103301, 121, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", 1, 4, "", 0, "vo_empress_103301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マヒル", 1, "vo_empress_103301_002", 103301, 122, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", 1, 4, "", 0, "vo_empress_103301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マヒル", 2, "vo_empress_103301_003", 103303, 123, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", 1, 4, "", 0, "vo_empress_103301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マヒル", 3, "vo_empress_103301_004", 103302, 124, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", 1, 4, "", 103301, "vo_empress_103301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユカリ", 1, "vo_empress_103401_001", 103401, 125, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", 1, 4, "", 0, "vo_empress_103401_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユカリ", 1, "vo_empress_103401_002", 103401, 126, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", 1, 4, "", 0, "vo_empress_103401_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユカリ", 2, "vo_empress_103401_003", 103403, 127, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", 1, 4, "", 0, "vo_empress_103401_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユカリ", 3, "vo_empress_103401_004", 103402, 128, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", 1, 4, "", 103401, "vo_empress_103401_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "キョウカ", 1, "vo_empress_103601_001", 103603, 129, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", 1, 4, "", 0, "vo_empress_103601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "キョウカ", 1, "vo_empress_103601_002", 103603, 130, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", 1, 4, "", 0, "vo_empress_103601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "キョウカ", 2, "vo_empress_103601_003", 103601, 131, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", 1, 4, "", 0, "vo_empress_103601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "キョウカ", 3, "vo_empress_103601_004", 103602, 132, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", 1, 4, "", 103601, "vo_empress_103601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "トモ", 1, "vo_empress_103701_001", 103701, 133, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", 1, 4, "", 0, "vo_empress_103701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "トモ", 1, "vo_empress_103701_002", 103701, 134, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", 1, 4, "", 0, "vo_empress_103701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "トモ", 2, "vo_empress_103701_003", 103701, 135, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", 1, 4, "", 0, "vo_empress_103701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "トモ", 3, "vo_empress_103701_004", 103702, 136, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", 1, 4, "", 103701, "vo_empress_103701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シオリ", 1, "vo_empress_103801_001", 103801, 137, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", 1, 4, "", 0, "vo_empress_103801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シオリ", 1, "vo_empress_103801_002", 103801, 138, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", 1, 4, "", 0, "vo_empress_103801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シオリ", 2, "vo_empress_103801_003", 103803, 139, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", 1, 4, "", 0, "vo_empress_103801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シオリ", 3, "vo_empress_103801_004", 103802, 140, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", 1, 4, "", 103801, "vo_empress_103801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アオイ", 1, "vo_empress_104001_001", 104001, 141, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", 1, 4, "", 0, "vo_empress_104001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アオイ", 1, "vo_empress_104001_002", 104002, 142, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", 1, 4, "", 0, "vo_empress_104001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アオイ", 2, "vo_empress_104001_003", 104003, 143, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", 1, 4, "", 0, "vo_empress_104001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アオイ", 3, "vo_empress_104001_004", 104002, 144, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", 1, 4, "", 104001, "vo_empress_104001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "チカ", 1, "vo_empress_104201_001", 104203, 145, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", 1, 4, "", 0, "vo_empress_104201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "チカ", 1, "vo_empress_104201_002", 104201, 146, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", 1, 4, "", 0, "vo_empress_104201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "チカ", 2, "vo_empress_104201_003", 104203, 147, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", 1, 4, "", 0, "vo_empress_104201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "チカ", 3, "vo_empress_104201_004", 104201, 148, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", 1, 4, "", 104201, "vo_empress_104201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マコト", 1, "vo_empress_104301_001", 104301, 149, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", 1, 4, "", 0, "vo_empress_104301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マコト", 1, "vo_empress_104301_002", 104301, 150, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", 1, 4, "", 0, "vo_empress_104301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マコト", 2, "vo_empress_104301_003", 104303, 151, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", 1, 4, "", 0, "vo_empress_104301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "マコト", 3, "vo_empress_104301_004", 104302, 152, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", 1, 4, "", 104301, "vo_empress_104301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イリヤ", 1, "vo_empress_104401_001", 104401, 153, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", 1, 4, "", 0, "vo_empress_104401_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イリヤ", 1, "vo_empress_104401_002", 104401, 154, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", 1, 4, "", 0, "vo_empress_104401_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イリヤ", 2, "vo_empress_104401_003", 104401, 155, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", 1, 4, "", 0, "vo_empress_104401_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イリヤ", 3, "vo_empress_104401_004", 104401, 156, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", 1, 4, "", 104401, "vo_empress_104401_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クウカ", 1, "vo_empress_104501_001", 104501, 157, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", 1, 4, "", 0, "vo_empress_104501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クウカ", 1, "vo_empress_104501_002", 104501, 158, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", 1, 4, "", 0, "vo_empress_104501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クウカ", 2, "vo_empress_104501_003", 104503, 159, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", 1, 4, "", 0, "vo_empress_104501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クウカ", 3, "vo_empress_104501_004", 104502, 160, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", 1, 4, "", 104501, "vo_empress_104501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "タマキ", 1, "vo_empress_104601_001", 104601, 161, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", 1, 4, "", 0, "vo_empress_104601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "タマキ", 1, "vo_empress_104601_002", 104601, 162, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", 1, 4, "", 0, "vo_empress_104601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "タマキ", 2, "vo_empress_104601_003", 104603, 163, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", 1, 4, "", 0, "vo_empress_104601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "タマキ", 3, "vo_empress_104601_004", 104602, 164, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", 1, 4, "", 104601, "vo_empress_104601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ジュン", 1, "vo_empress_104701_001", 104701, 165, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", 1, 4, "", 0, "vo_empress_104701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ジュン", 1, "vo_empress_104701_002", 104701, 166, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", 1, 4, "", 0, "vo_empress_104701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ジュン", 2, "vo_empress_104701_003", 104701, 167, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", 1, 4, "", 0, "vo_empress_104701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ジュン", 3, "vo_empress_104701_004", 104701, 168, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", 1, 4, "", 104701, "vo_empress_104701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミフユ", 1, "vo_empress_104801_001", 104801, 169, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", 1, 4, "", 0, "vo_empress_104801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミフユ", 1, "vo_empress_104801_002", 104801, 170, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", 1, 4, "", 0, "vo_empress_104801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミフユ", 2, "vo_empress_104801_003", 104803, 171, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", 1, 4, "", 0, "vo_empress_104801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミフユ", 3, "vo_empress_104801_004", 104802, 172, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", 1, 4, "", 104801, "vo_empress_104801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シズル", 1, "vo_empress_104901_001", 104902, 173, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", 1, 4, "", 0, "vo_empress_104901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シズル", 1, "vo_empress_104901_002", 104902, 174, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", 1, 4, "", 0, "vo_empress_104901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シズル", 2, "vo_empress_104901_003", 104903, 175, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", 1, 4, "", 0, "vo_empress_104901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シズル", 3, "vo_empress_104901_004", 104902, 176, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", 1, 4, "", 104901, "vo_empress_104901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミサキ", 1, "vo_empress_105001_001", 105001, 177, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", 1, 4, "", 0, "vo_empress_105001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミサキ", 1, "vo_empress_105001_002", 105001, 178, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", 1, 4, "", 0, "vo_empress_105001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミサキ", 2, "vo_empress_105001_003", 105003, 179, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", 1, 4, "", 0, "vo_empress_105001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミサキ", 3, "vo_empress_105001_004", 105002, 180, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", 1, 4, "", 105001, "vo_empress_105001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミツキ", 1, "vo_empress_105101_001", 105101, 181, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", 1, 4, "", 0, "vo_empress_105101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミツキ", 1, "vo_empress_105101_002", 105101, 182, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", 1, 4, "", 0, "vo_empress_105101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミツキ", 2, "vo_empress_105101_003", 105101, 183, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", 1, 4, "", 0, "vo_empress_105101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミツキ", 3, "vo_empress_105101_004", 105101, 184, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", 1, 4, "", 105101, "vo_empress_105101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リマ", 1, "vo_empress_105201_001", 105201, 185, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", 1, 4, "", 0, "vo_empress_105201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "リマ", 4002, "vo_empress_105201_002", 105201, 186, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 1, 4, 1, 0, "vo_empress_105201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リマ", 2, "vo_empress_105201_003", 105201, 187, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", 1, 4, "", 0, "vo_empress_105201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リマ", 3, "vo_empress_105201_004", 105202, 188, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", 1, 4, "", 105201, "vo_empress_105201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "モニカ", 1, "vo_empress_105301_001", 105303, 189, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", 1, 4, "", 0, "vo_empress_105301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "モニカ", 1, "vo_empress_105301_002", 105301, 190, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", 1, 4, "", 0, "vo_empress_105301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "モニカ", 2, "vo_empress_105301_003", 105301, 191, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", 1, 4, "", 0, "vo_empress_105301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "モニカ", 3, "vo_empress_105301_004", 105302, 192, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", 1, 4, "", 105301, "vo_empress_105301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ツムギ", 1, "vo_empress_105401_001", 105401, 193, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", 1, 4, "", 0, "vo_empress_105401_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ツムギ", 4002, "vo_empress_105401_002", 105403, 194, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 1, 4, 1, 0, "vo_empress_105401_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ツムギ", 2, "vo_empress_105401_003", 105403, 195, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", 1, 4, "", 0, "vo_empress_105401_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ツムギ", 3, "vo_empress_105401_004", 105401, 196, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", 1, 4, "", 105401, "vo_empress_105401_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アユミ", 1, "vo_empress_105501_001", 105503, 197, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", 1, 4, "", 0, "vo_empress_105501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アユミ", 1, "vo_empress_105501_002", 105501, 198, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", 1, 4, "", 0, "vo_empress_105501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アユミ", 2, "vo_empress_105501_003", 105503, 199, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", 1, 4, "", 0, "vo_empress_105501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アユミ", 3, "vo_empress_105501_004", 105502, 200, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", 1, 4, "", 105501, "vo_empress_105501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルカ", 1, "vo_empress_105601_001", 105601, 201, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", 1, 4, "", 0, "vo_empress_105601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルカ", 1, "vo_empress_105601_002", 105601, 202, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", 1, 4, "", 0, "vo_empress_105601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルカ", 2, "vo_empress_105601_003", 105603, 203, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", 1, 4, "", 0, "vo_empress_105601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルカ", 3, "vo_empress_105601_004", 105602, 204, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", 1, 4, "", 105601, "vo_empress_105601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ペコリーヌ", 1, "vo_empress_105801_001", 105803, 205, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", 1, 4, "", 0, "vo_empress_105801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ペコリーヌ", 4003, "vo_empress_105801_002", 105801, 206, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 1, 4, 1, 0, "vo_empress_105801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ペコリーヌ", 2, "vo_empress_105801_003", 105803, 207, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", 1, 4, "", 0, "vo_empress_105801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ペコリーヌ", 3, "vo_empress_105801_004", 105802, 208, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", 1, 4, "", 105801, "vo_empress_105801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "コッコロ", 1, "vo_empress_105901_001", 105903, 209, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", 1, 4, "", 0, "vo_empress_105901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "コッコロ", 1, "vo_empress_105901_002", 105905, 210, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", 1, 4, "", 0, "vo_empress_105901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "コッコロ", 2, "vo_empress_105901_003", 105903, 211, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", 1, 4, "", 0, "vo_empress_105901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "コッコロ", 3, "vo_empress_105901_004", 105902, 212, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", 1, 4, "", 105901, "vo_empress_105901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "キャル", 4005, "vo_empress_106001_001", 106001, 213, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 1, 4, 1, 0, "vo_empress_106001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "キャル", 1, "vo_empress_106001_002", 106003, 214, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", 1, 4, "", 0, "vo_empress_106001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "キャル", 2, "vo_empress_106001_003", 106003, 215, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", 1, 4, "", 0, "vo_empress_106001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "キャル", 3, "vo_empress_106001_004", 106002, 216, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", 1, 4, "", 106001, "vo_empress_106001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ノウェム", 1, "vo_empress_106101_001", 106102, 217, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", 1, 4, "", 0, "vo_empress_106101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ノウェム", 1, "vo_empress_106101_002", 106101, 218, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", 1, 4, "", 0, "vo_empress_106101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ノウェム", 2, "vo_empress_106101_003", 106103, 219, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", 1, 4, "", 0, "vo_empress_106101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ノウェム", 3, "vo_empress_106101_004", 106102, 220, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", 1, 4, "", 106101, "vo_empress_106101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シェフィ", 1, "vo_empress_106401_001", 106401, 221, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", 1, 4, "", 0, "vo_empress_106401_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "シェフィ", 4004, "vo_empress_106401_002", 106403, 222, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 1, 4, 1, 0, "vo_empress_106401_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シェフィ", 2, "vo_empress_106401_003", 106401, 223, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", 1, 4, "", 0, "vo_empress_106401_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シェフィ", 3, "vo_empress_106401_004", 106402, 224, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", 1, 4, "", 106401, "vo_empress_106401_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カヤ", 1, "vo_empress_106501_001", 106501, 225, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", 1, 4, "", 0, "vo_empress_106501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カヤ", 1, "vo_empress_106501_002", 106501, 226, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", 1, 4, "", 0, "vo_empress_106501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カヤ", 2, "vo_empress_106501_003", 106503, 227, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", 1, 4, "", 0, "vo_empress_106501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カヤ", 3, "vo_empress_106501_004", 106501, 228, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", 1, 4, "", 106501, "vo_empress_106501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イノリ", 1, "vo_empress_106601_001", 106603, 229, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", 1, 4, "", 0, "vo_empress_106601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イノリ", 1, "vo_empress_106601_002", 106601, 230, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", 1, 4, "", 0, "vo_empress_106601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イノリ", 2, "vo_empress_106601_003", 106603, 231, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", 1, 4, "", 0, "vo_empress_106601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イノリ", 3, "vo_empress_106601_004", 106602, 232, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", 1, 4, "", 106601, "vo_empress_106601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ホマレ", 1, "vo_empress_106701_001", 106701, 233, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", 1, 4, "", 0, "vo_empress_106701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ホマレ", 1, "vo_empress_106701_002", 106701, 234, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", 1, 4, "", 0, "vo_empress_106701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ホマレ", 2, "vo_empress_106701_003", 106703, 235, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", 1, 4, "", 0, "vo_empress_106701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ホマレ", 3, "vo_empress_106701_004", 106702, 236, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", 1, 4, "", 106701, "vo_empress_106701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ラビリスタ", 1, "vo_empress_106801_001", 106802, 237, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", 1, 4, "", 0, "vo_empress_106801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ラビリスタ", 4005, "vo_empress_106801_002", 106801, 238, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 1, 4, 1, 0, "vo_empress_106801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ラビリスタ", 2, "vo_empress_106801_003", 106801, 239, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", 1, 4, "", 0, "vo_empress_106801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ラビリスタ", 3, "vo_empress_106801_004", 106802, 240, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", 1, 4, "", 106801, "vo_empress_106801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ネネカ", 4005, "vo_empress_107001_001", 107001, 241, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 1, 4, 1, 0, "vo_empress_107001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネネカ", 1, "vo_empress_107001_002", 107001, 242, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", 1, 4, "", 0, "vo_empress_107001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネネカ", 2, "vo_empress_107001_003", 107001, 243, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", 1, 4, "", 0, "vo_empress_107001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネネカ", 3, "vo_empress_107001_004", 107002, 244, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", 1, 4, "", 107001, "vo_empress_107001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クリスティーナ", 1, "vo_empress_107101_001", 107101, 245, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", 1, 4, "", 0, "vo_empress_107101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "クリスティーナ", 4005, "vo_empress_107101_002", 107101, 246, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 1, 4, 1, 0, "vo_empress_107101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クリスティーナ", 2, "vo_empress_107101_003", 107103, 247, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", 1, 4, "", 0, "vo_empress_107101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クリスティーナ", 3, "vo_empress_107101_004", 107102, 248, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", 1, 4, "", 107101, "vo_empress_107101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クロエ", 1, "vo_empress_110801_001", 110801, 249, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", 1, 4, "", 0, "vo_empress_110801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "クロエ", 4005, "vo_empress_110801_002", 110801, 250, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 1, 4, 1, 0, "vo_empress_110801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クロエ", 2, "vo_empress_110801_003", 110803, 251, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", 1, 4, "", 0, "vo_empress_110801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クロエ", 3, "vo_empress_110801_004", 110802, 252, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", 1, 4, "", 110801, "vo_empress_110801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "チエル", 1, "vo_empress_110901_001", 110901, 253, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", 1, 4, "", 0, "vo_empress_110901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "チエル", 1, "vo_empress_110901_002", 110901, 254, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", 1, 4, "", 0, "vo_empress_110901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "チエル", 2, "vo_empress_110901_003", 110903, 255, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", 1, 4, "", 0, "vo_empress_110901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "チエル", 3, "vo_empress_110901_004", 110902, 256, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", 1, 4, "", 110901, "vo_empress_110901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユニ", 1, "vo_empress_111001_001", 111001, 257, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", 1, 4, "", 0, "vo_empress_111001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユニ", 1, "vo_empress_111001_002", 111001, 258, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", 1, 4, "", 0, "vo_empress_111001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユニ", 2, "vo_empress_111001_003", 111003, 259, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", 1, 4, "", 0, "vo_empress_111001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユニ", 3, "vo_empress_111001_004", 111002, 260, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", 1, 4, "", 111001, "vo_empress_111001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クレジッタ", 1, "vo_empress_118001_001", 118001, 261, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", 1, 4, "", 0, "vo_empress_118001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クレジッタ", 1, "vo_empress_118001_002", 118003, 262, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", 1, 4, "", 0, "vo_empress_118001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クレジッタ", 2, "vo_empress_118001_003", 118003, 263, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", 1, 4, "", 0, "vo_empress_118001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クレジッタ", 3, "vo_empress_118001_004", 118002, 264, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", 1, 4, "", 118001, "vo_empress_118001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ランファ", 1, "vo_empress_118101_001", 118101, 265, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", 1, 4, "", 0, "vo_empress_118101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ランファ", 1, "vo_empress_118101_002", 118101, 266, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", 1, 4, "", 0, "vo_empress_118101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ランファ", 2, "vo_empress_118101_003", 118103, 267, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", 1, 4, "", 0, "vo_empress_118101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ランファ", 3, "vo_empress_118101_004", 118102, 268, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", 1, 4, "", 118101, "vo_empress_118101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ミソラ", 4005, "vo_empress_118201_001", 118201, 269, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 1, 4, 1, 0, "vo_empress_118201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミソラ", 1, "vo_empress_118201_002", 118201, 270, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", 1, 4, "", 0, "vo_empress_118201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミソラ", 2, "vo_empress_118201_003", 118202, 271, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", 1, 4, "", 0, "vo_empress_118201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ミソラ", 3, "vo_empress_118201_004", 118202, 272, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", 1, 4, "", 118201, "vo_empress_118201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カリン", 1, "vo_empress_118501_001", 118501, 273, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", 1, 4, "", 0, "vo_empress_118501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カリン", 1, "vo_empress_118501_002", 118502, 274, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", 1, 4, "", 0, "vo_empress_118501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カリン", 2, "vo_empress_118501_003", 118503, 275, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", 1, 4, "", 0, "vo_empress_118501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カリン", 3, "vo_empress_118501_004", 118502, 276, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", 1, 4, "", 118501, "vo_empress_118501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネビア", 1, "vo_empress_118601_001", 118601, 277, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", 1, 4, "", 0, "vo_empress_118601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネビア", 1, "vo_empress_118601_002", 118601, 278, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", 1, 4, "", 0, "vo_empress_118601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネビア", 2, "vo_empress_118601_003", 118603, 279, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", 1, 4, "", 0, "vo_empress_118601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネビア", 3, "vo_empress_118601_004", 118602, 280, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", 1, 4, "", 118601, "vo_empress_118601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴァンピィ", 1, "vo_empress_122301_001", 122303, 281, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", 1, 4, "", 0, "vo_empress_122301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴァンピィ", 1, "vo_empress_122301_002", 122302, 282, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", 1, 4, "", 0, "vo_empress_122301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴァンピィ", 2, "vo_empress_122301_003", 122303, 283, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", 1, 4, "", 0, "vo_empress_122301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴァンピィ", 3, "vo_empress_122301_004", 122302, 284, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", 1, 4, "", 122301, "vo_empress_122301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アメス", 1, "vo_empress_123001_001", 123002, 285, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", 1, 4, "", 0, "vo_empress_123001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アメス", 1, "vo_empress_123001_002", 123001, 286, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", 1, 4, "", 0, "vo_empress_123001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アメス", 2, "vo_empress_123001_003", 123003, 287, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", 1, 4, "", 0, "vo_empress_123001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アメス", 3, "vo_empress_123001_004", 123002, 288, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", 1, 4, "", 123001, "vo_empress_123001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネア", 1, "vo_empress_123301_001", 123301, 289, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", 1, 4, "", 0, "vo_empress_123301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネア", 1, "vo_empress_123301_002", 123301, 290, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", 1, 4, "", 0, "vo_empress_123301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネア", 2, "vo_empress_123301_003", 123303, 291, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", 1, 4, "", 0, "vo_empress_123301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネア", 3, "vo_empress_123301_004", 123302, 292, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", 1, 4, "", 123301, "vo_empress_123301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クローチェ", 1, "vo_empress_126401_001", 126401, 293, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", 1, 4, "", 0, "vo_empress_126401_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クローチェ", 1, "vo_empress_126401_002", 126401, 294, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", 1, 4, "", 0, "vo_empress_126401_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クローチェ", 2, "vo_empress_126401_003", 126403, 295, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", 1, 4, "", 0, "vo_empress_126401_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クローチェ", 3, "vo_empress_126401_004", 126402, 296, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", 1, 4, "", 126401, "vo_empress_126401_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ライラエル", 1, "vo_empress_126501_001", 126501, 297, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", 1, 4, "", 0, "vo_empress_126501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ライラエル", 4002, "vo_empress_126501_002", 126506, 298, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 1, 4, 1, 0, "vo_empress_126501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ライラエル", 2, "vo_empress_126501_003", 126503, 299, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", 1, 4, "", 0, "vo_empress_126501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ライラエル", 3, "vo_empress_126501_004", 126502, 300, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", 1, 4, "", 126501, "vo_empress_126501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "リンド", 4002, "vo_empress_127701_001", 127701, 301, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 1, 4, 1, 0, "vo_empress_127701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リンド", 1, "vo_empress_127701_002", 127701, 302, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", 1, 4, "", 0, "vo_empress_127701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リンド", 2, "vo_empress_127701_003", 127703, 303, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", 1, 4, "", 0, "vo_empress_127701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リンド", 3, "vo_empress_127701_004", 127702, 304, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", 1, 4, "", 127701, "vo_empress_127701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴルム", 1, "vo_empress_127801_001", 127801, 305, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", 1, 4, "", 0, "vo_empress_127801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ヴルム", 4002, "vo_empress_127801_002", 127801, 306, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 1, 4, 1, 0, "vo_empress_127801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴルム", 2, "vo_empress_127801_003", 127803, 307, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", 1, 4, "", 0, "vo_empress_127801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴルム", 3, "vo_empress_127801_004", 127802, 308, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", 1, 4, "", 127801, "vo_empress_127801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "エリス", 4005, "vo_empress_129001_001", 129001, 309, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 1, 4, 1, 0, "vo_empress_129001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "エリス", 1, "vo_empress_129001_002", 129001, 310, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", 1, 4, "", 0, "vo_empress_129001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "エリス", 2, "vo_empress_129001_003", 129003, 311, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", 1, 4, "", 0, "vo_empress_129001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "エリス", 3, "vo_empress_129001_004", 129002, 312, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", 1, 4, "", 129001, "vo_empress_129001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アネモネ", 1, "vo_empress_129601_001", 129601, 313, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", 1, 4, "", 0, "vo_empress_129601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アネモネ", 1, "vo_empress_129601_002", 129601, 314, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", 1, 4, "", 0, "vo_empress_129601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アネモネ", 2, "vo_empress_129601_003", 129603, 315, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", 1, 4, "", 0, "vo_empress_129601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アネモネ", 3, "vo_empress_129601_004", 129601, 316, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", 1, 4, "", 129601, "vo_empress_129601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネフィ＝ネラ", 1, "vo_empress_129701_001", 129701, 317, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", 1, 4, "", 0, "vo_empress_129701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネフィ＝ネラ", 1, "vo_empress_129701_002", 129701, 318, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", 1, 4, "", 0, "vo_empress_129701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネフィ＝ネラ", 2, "vo_empress_129701_003", 129703, 319, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", 1, 4, "", 0, "vo_empress_129701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ネフィ＝ネラ", 3, "vo_empress_129701_004", 129702, 320, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", 1, 4, "", 129701, "vo_empress_129701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ヤマト", 4003, "vo_empress_130001_001", 130001, 321, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 1, 4, 1, 0, "vo_empress_130001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヤマト", 1, "vo_empress_130001_002", 130001, 322, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", 1, 4, "", 0, "vo_empress_130001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヤマト", 2, "vo_empress_130001_003", 130003, 323, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", 1, 4, "", 0, "vo_empress_130001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヤマト", 3, "vo_empress_130001_004", 130002, 324, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", 1, 4, "", 130001, "vo_empress_130001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ワカナ", 1, "vo_empress_130101_001", 130101, 325, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", 1, 4, "", 0, "vo_empress_130101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ワカナ", 1, "vo_empress_130101_002", 130101, 326, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", 1, 4, "", 0, "vo_empress_130101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ワカナ", 2, "vo_empress_130101_003", 130103, 327, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", 1, 4, "", 0, "vo_empress_130101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ワカナ", 3, "vo_empress_130101_004", 130102, 328, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", 1, 4, "", 130101, "vo_empress_130101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "フブキ", 1, "vo_empress_130201_001", 130201, 329, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", 1, 4, "", 0, "vo_empress_130201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "フブキ", 1, "vo_empress_130201_002", 130201, 330, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", 1, 4, "", 0, "vo_empress_130201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "フブキ", 2, "vo_empress_130201_003", 130203, 331, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", 1, 4, "", 0, "vo_empress_130201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "フブキ", 3, "vo_empress_130201_004", 130202, 332, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", 1, 4, "", 130201, "vo_empress_130201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クルル", 1, "vo_empress_130901_001", 130901, 333, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", 1, 4, "", 0, "vo_empress_130901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クルル", 1, "vo_empress_130901_002", 130901, 334, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", 1, 4, "", 0, "vo_empress_130901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クルル", 2, "vo_empress_130901_003", 130903, 335, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", 1, 4, "", 0, "vo_empress_130901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クルル", 3, "vo_empress_130901_004", 130902, 336, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", 1, 4, "", 130901, "vo_empress_130901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルイズマリー", 1, "vo_empress_132301_001", 132301, 337, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", 1, 4, "", 0, "vo_empress_132301_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルイズマリー", 1, "vo_empress_132301_002", 132301, 338, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", 1, 4, "", 0, "vo_empress_132301_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルイズマリー", 2, "vo_empress_132301_003", 132303, 339, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", 1, 4, "", 0, "vo_empress_132301_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルイズマリー", 3, "vo_empress_132301_004", 132302, 340, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", 1, 4, "", 132301, "vo_empress_132301_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イロハ", 1, "vo_empress_132401_001", 132401, 341, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", 1, 4, "", 0, "vo_empress_132401_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イロハ", 1, "vo_empress_132401_002", 132401, 342, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", 1, 4, "", 0, "vo_empress_132401_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イロハ", 2, "vo_empress_132401_003", 132401, 343, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", 1, 4, "", 0, "vo_empress_132401_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "イロハ", 3, "vo_empress_132401_004", 132402, 344, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", 1, 4, "", 132401, "vo_empress_132401_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ソノ", 1, "vo_empress_132501_001", 132501, 345, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", 1, 4, "", 0, "vo_empress_132501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ソノ", 1, "vo_empress_132501_002", 132501, 346, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", 1, 4, "", 0, "vo_empress_132501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ソノ", 2, "vo_empress_132501_003", 132503, 347, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", 1, 4, "", 0, "vo_empress_132501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ソノ", 3, "vo_empress_132501_004", 132502, 348, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", 1, 4, "", 132501, "vo_empress_132501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "グレイス", 1, "vo_empress_133001_001", 133001, 349, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", 1, 4, "", 0, "vo_empress_133001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "グレイス", 4001, "vo_empress_133001_002", 133003, 350, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 1, 4, 1, 0, "vo_empress_133001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "グレイス", 2, "vo_empress_133001_003", 133003, 351, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", 1, 4, "", 0, "vo_empress_133001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "グレイス", 3, "vo_empress_133001_004", 133002, 352, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", 1, 4, "", 133001, "vo_empress_133001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴァイオレット", 1, "vo_empress_133101_001", 133101, 353, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", 1, 4, "", 0, "vo_empress_133101_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ヴァイオレット", 4001, "vo_empress_133101_002", 133101, 354, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 1, 4, 1, 0, "vo_empress_133101_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴァイオレット", 2, "vo_empress_133101_003", 133103, 355, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", 1, 4, "", 0, "vo_empress_133101_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ヴァイオレット", 3, "vo_empress_133101_004", 133102, 356, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", 1, 4, "", 133101, "vo_empress_133101_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "メドゥーサ", 1, "vo_empress_133601_001", 133601, 357, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", 1, 4, "", 0, "vo_empress_133601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "メドゥーサ", 1, "vo_empress_133601_002", 133601, 358, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", 1, 4, "", 0, "vo_empress_133601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "メドゥーサ", 2, "vo_empress_133601_003", 133603, 359, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", 1, 4, "", 0, "vo_empress_133601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "メドゥーサ", 3, "vo_empress_133601_004", 133602, 360, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", 1, 4, "", 133601, "vo_empress_133601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ホウオウ", 1, "vo_empress_134701_001", 134701, 361, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", 1, 4, "", 0, "vo_empress_134701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ホウオウ", 1, "vo_empress_134701_002", 134701, 362, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", 1, 4, "", 0, "vo_empress_134701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ホウオウ", 2, "vo_empress_134701_003", 134703, 363, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", 1, 4, "", 0, "vo_empress_134701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ホウオウ", 3, "vo_empress_134701_004", 134702, 364, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", 1, 4, "", 134701, "vo_empress_134701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カノン", 1, "vo_empress_134901_001", 134901, 365, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", 1, 4, "", 0, "vo_empress_134901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カノン", 1, "vo_empress_134901_002", 134901, 366, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", 1, 4, "", 0, "vo_empress_134901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カノン", 2, "vo_empress_134901_003", 134903, 367, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", 1, 4, "", 0, "vo_empress_134901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "カノン", 3, "vo_empress_134901_004", 134902, 368, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", 1, 4, "", 134901, "vo_empress_134901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アイラ", 1, "vo_empress_135501_001", 135501, 369, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", 1, 4, "", 0, "vo_empress_135501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "アイラ", 4005, "vo_empress_135501_002", 135501, 370, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 1, 4, 1, 0, "vo_empress_135501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アイラ", 2, "vo_empress_135501_003", 135503, 371, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", 1, 4, "", 0, "vo_empress_135501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アイラ", 3, "vo_empress_135501_004", 135502, 372, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", 1, 4, "", 135501, "vo_empress_135501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シナツ", 1, "vo_empress_135601_001", 135601, 373, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", 1, 4, "", 0, "vo_empress_135601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シナツ", 1, "vo_empress_135601_002", 135601, 374, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", 1, 4, "", 0, "vo_empress_135601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シナツ", 2, "vo_empress_135601_003", 135603, 375, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", 1, 4, "", 0, "vo_empress_135601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "シナツ", 3, "vo_empress_135601_004", 135602, 376, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", 1, 4, "", 135601, "vo_empress_135601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ユキノ", 4001, "vo_empress_135801_001", 135801, 377, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 1, 4, 1, 0, "vo_empress_135801_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユキノ", 1, "vo_empress_135801_002", 135801, 378, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", 1, 4, "", 0, "vo_empress_135801_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユキノ", 2, "vo_empress_135801_003", 135803, 379, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", 1, 4, "", 0, "vo_empress_135801_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ユキノ", 3, "vo_empress_135801_004", 135802, 380, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", 1, 4, "", 135801, "vo_empress_135801_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "サツキ", 4001, "vo_empress_135901_001", 135903, 381, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 1, 4, 1, 0, "vo_empress_135901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "サツキ", 1, "vo_empress_135901_002", 135901, 382, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", 1, 4, "", 0, "vo_empress_135901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "サツキ", 2, "vo_empress_135901_003", 135901, 383, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", 1, 4, "", 0, "vo_empress_135901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "サツキ", 3, "vo_empress_135901_004", 135902, 384, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", 1, 4, "", 135901, "vo_empress_135901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アラクネ", 1, "vo_empress_136001_001", 136001, 385, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", 1, 4, "", 0, "vo_empress_136001_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "アラクネ", 4003, "vo_empress_136001_002", 136001, 386, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 1, 4, 1, 0, "vo_empress_136001_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アラクネ", 2, "vo_empress_136001_003", 136003, 387, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", 1, 4, "", 0, "vo_empress_136001_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "アラクネ", 3, "vo_empress_136001_004", 136002, 388, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", 1, 4, "", 136001, "vo_empress_136001_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ナーナ", 1, "vo_empress_136201_001", 136201, 389, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", 1, 4, "", 0, "vo_empress_136201_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ナーナ", 1, "vo_empress_136201_002", 136201, 390, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", 1, 4, "", 0, "vo_empress_136201_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ナーナ", 2, "vo_empress_136201_003", 136201, 391, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", 1, 4, "", 0, "vo_empress_136201_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ナーナ", 3, "vo_empress_136201_004", 136202, 392, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", 1, 4, "", 136201, "vo_empress_136201_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "ルルィ", 4001, "vo_empress_136901_001", 136903, 393, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 1, 4, 1, 0, "vo_empress_136901_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルルィ", 1, "vo_empress_136901_002", 136901, 394, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", 1, 4, "", 0, "vo_empress_136901_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルルィ", 2, "vo_empress_136901_003", 136903, 395, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", 1, 4, "", 0, "vo_empress_136901_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ルルィ", 3, "vo_empress_136901_004", 136902, 396, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", 1, 4, "", 136901, "vo_empress_136901_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リリ", 1, "vo_empress_139501_001", 139501, 397, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", 1, 4, "", 0, "vo_empress_139501_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "リリ", 4002, "vo_empress_139501_002", 139503, 398, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 1, 4, 1, 0, "vo_empress_139501_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リリ", 2, "vo_empress_139501_003", 139503, 399, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", 1, 4, "", 0, "vo_empress_139501_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "リリ", 3, "vo_empress_139501_004", 139502, 400, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", 1, 4, "", 125801, "vo_empress_139501_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クリア", 1, "vo_empress_139601_001", 139603, 401, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", 1, 4, "", 0, "vo_empress_139601_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (10000, 3, "クリア", 4002, "vo_empress_139601_002", 139603, 402, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 1, 4, 1, 0, "vo_empress_139601_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クリア", 2, "vo_empress_139601_003", 139603, 403, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", 1, 4, "", 0, "vo_empress_139601_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "クリア", 3, "vo_empress_139601_004", 139601, 404, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", 1, 4, "", 126001, "vo_empress_139601_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "プレシア", 1, "vo_empress_139701_001", 139701, 405, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", 1, 4, "", 0, "vo_empress_139701_001");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "プレシア", 1, "vo_empress_139701_002", 139701, 406, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", 1, 4, "", 0, "vo_empress_139701_002");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "プレシア", 2, "vo_empress_139701_003", 139703, 407, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", 1, 4, "", 0, "vo_empress_139701_003");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "プレシア", 3, "vo_empress_139701_004", 139702, 408, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", 1, 4, "", 126101, "vo_empress_139701_004");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", 5, "ティア", 3, "vo_empress_140301_004", 140301, 409, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", 1, 4, "", 140301, "vo_empress_140301_004");
